// Customer Service Agent - Handle support requests

const input = $input.first().json;
const body = input.body || input;

const taskId = body.task_id || `support_${Date.now()}`;

// Parse support request
const ticket = {
  task_id: taskId,
  email: body.from?.email || body.from || body.email || '',
  name: body.from?.name || body.name || '',
  subject: body.subject || 'Support Request',
  description: body.snippet || body.message || body.description || '',
  source: body.source || 'email',
  timestamp: new Date().toISOString()
};

// Determine priority based on content
const desc = ticket.description.toLowerCase();
let priority = 'Medium';
let category = 'General';

// Priority detection
if (desc.includes('urgent') || desc.includes('emergency') || desc.includes('down') || desc.includes('broken')) {
  priority = 'High';
}
if (desc.includes('asap') || desc.includes('critical')) {
  priority = 'Urgent';
}

// Category detection
if (desc.includes('website') || desc.includes('site') || desc.includes('page')) {
  category = 'Website';
} else if (desc.includes('email') || desc.includes('gmail')) {
  category = 'Email';
} else if (desc.includes('automation') || desc.includes('workflow') || desc.includes('n8n')) {
  category = 'Automation';
} else if (desc.includes('billing') || desc.includes('invoice') || desc.includes('payment')) {
  category = 'Billing';
}

ticket.priority = priority;
ticket.category = category;

return ticket;

// Return completion
const ticket = $('Parse Support Request').first().json;

return {
  agent: 'customer_service',
  status: 'completed',
  ticket_email: ticket.email,
  ticket_priority: ticket.priority,
  ticket_category: ticket.category,
  zoho_ticket_created: true,
  confirmation_sent: true,
  timestamp: new Date().toISOString()
};
